const fs = require('fs');
const path = require('path');

const errorsDir = 'packages/payload/src/errors';

const subclassUpdates = {
  'DuplicateCollection.ts': { code: 'DUPLICATE_COLLECTION', pattern: /super\(\`Collection/, replacement: \"super(\n      'DUPLICATE_COLLECTION',\n      \`Collection\" },
  'DuplicateFieldName.ts': { code: 'DUPLICATE_FIELD_NAME', pattern: /super\(\n\s+\`A field/, replacement: \"super(\n      'DUPLICATE_FIELD_NAME',\n      \\\`A field\" },
  'DuplicateGlobal.ts': { code: 'DUPLICATE_GLOBAL', pattern: /super\(\`Global label/, replacement: \"super('DUPLICATE_GLOBAL', \\\`Global label\" },
  'ErrorDeletingFile.ts': { code: 'ERROR_DELETING_FILE' },
  'FileRetrievalError.ts': { code: 'FILE_RETRIEVAL_ERROR' },
  'FileUploadError.ts': { code: 'FILE_UPLOAD_ERROR' },
  'Forbidden.ts': { code: 'FORBIDDEN' },
  'InvalidConfiguration.ts': { code: 'INVALID_CONFIGURATION' },
  'InvalidFieldJoin.ts': { code: 'INVALID_FIELD_JOIN' },
  'InvalidFieldName.ts': { code: 'INVALID_FIELD_NAME' },
  'InvalidFieldRelationship.ts': { code: 'INVALID_FIELD_RELATIONSHIP' },
  'InvalidSchema.ts': { code: 'INVALID_SCHEMA' },
  'Locked.ts': { code: 'LOCKED' },
  'LockedAuth.ts': { code: 'LOCKED_AUTH' },
  'MissingCollectionLabel.ts': { code: 'MISSING_COLLECTION_LABEL' },
  'MissingEditorProp.ts': { code: 'MISSING_EDITOR_PROP' },
  'MissingFieldInputOptions.ts': { code: 'MISSING_FIELD_INPUT_OPTIONS' },
  'MissingFieldType.ts': { code: 'MISSING_FIELD_TYPE' },
  'MissingFile.ts': { code: 'MISSING_FILE' },
  'NotFound.ts': { code: 'NOT_FOUND' },
  'QueryError.ts': { code: 'QUERY_ERROR' },
  'ReservedFieldName.ts': { code: 'RESERVED_FIELD_NAME' },
  'TimestampsRequired.ts': { code: 'TIMESTAMPS_REQUIRED' },
  'UnauthorizedError.ts': { code: 'UNAUTHORIZED' },
  'UnverifiedEmail.ts': { code: 'UNVERIFIED_EMAIL' },
  'ValidationError.ts': { code: 'VALIDATION_ERROR' },
};

for (const [file, config] of Object.entries(subclassUpdates)) {
  const filePath = path.join(errorsDir, file);
  let content = fs.readFileSync(filePath, 'utf8');

  // Generic approach: find 'super(' and add the error code as first arg
  // The super call is always inside the constructor
  // We need to add the error code string as the first argument

  // Match the first 'super(' after 'constructor' and insert the error code
  const superPattern = /(\n\s+)(super\(\n?\s*)/;
  const match = content.match(superPattern);
  if (match) {
    const indent = match[1];
    const superStart = match[2];
    if (superStart.includes('\n')) {
      // multiline super call - add error code on new line after super(
      content = content.replace(superPattern, indent + 'super(\n      ' + \"'\" + config.code + \"',\n      \");
    } else {
      // single line super( - add error code inline
      content = content.replace(superPattern, indent + \"super('\" + config.code + \"', \");
    }
    fs.writeFileSync(filePath, content);
    console.log('Updated:', file);
  } else {
    console.log('FAILED to match:', file);
  }
}
"

