  if (statusCode === '423' || statusCode === 'httpStatus.LOCKED') return 'LOCKED';
  if (statusCode === 'httpStatus.REQUEST_ENTITY_TOO_LARGE') return 'REQUEST_TOO_LARGE';

  // Based on message content
  if (msg.includes('not found')) return 'NOT_FOUND';
  if (msg.includes('not supported')) return 'NOT_SUPPORTED';
  if (msg.includes('missing')) return 'BAD_REQUEST';
  if (msg.includes('invalid')) return 'BAD_REQUEST';
  if (msg.includes('unauthorized') || msg.includes('no user')) return 'UNAUTHORIZED';
  if (msg.includes('forbidden') || msg.includes('not allowed') || msg.includes('lock you out')) return 'FORBIDDEN';
  if (msg.includes('upload') || msg.includes('file')) return 'FILE_ERROR';
  if (msg.includes('disabled')) return 'FORBIDDEN';
  if (msg.includes('failed') || msg.includes('error')) return 'INTERNAL_ERROR';

  // Based on file path
  if (file.includes('auth/')) return 'AUTH_ERROR';
  if (file.includes('upload')) return 'UPLOAD_ERROR';

  return 'INTERNAL_ERROR';
}

